-- VYRA · Plan biegowy 2026/27 (tygodnie 2–32) dla zawodnika „Kacper Adamczyk”.
-- Tydzień 2 zaczyna się w poniedziałek 2 listopada 2026, kolejne tygodnie po kolei.
-- Uruchom raz w Supabase → SQL Editor. Ponowne uruchomienie nic nie zdubluje.

do $$
declare
  v_ath   uuid;
  v_coach uuid;
  v_plan  uuid;
  v_s     uuid;
  v_n     int := 0;
  e       jsonb;
begin
  select id into v_ath from public.profiles
   where role = 'athlete' and lower(trim(full_name)) = lower('Kacper Adamczyk')
   order by created_at limit 1;
  if v_ath is null then
    raise exception 'Nie znaleziono konta ZAWODNIKA o nazwie "Kacper Adamczyk". Załóż je z linku zaproszenia (Zawodnicy → Zaproś) i uruchom ponownie.';
  end if;

  select ca.coach_id into v_coach
    from public.coach_athletes ca join public.profiles p on p.id = ca.coach_id
   where ca.athlete_id = v_ath and ca.status = 'active'
   order by (p.staff_role = 'founder') desc, ca.created_at limit 1;
  if v_coach is null then
    raise exception 'Zawodnik "Kacper Adamczyk" nie ma aktywnego trenera.';
  end if;

  if exists (select 1 from public.training_plans where athlete_id = v_ath and name = 'Plan biegowy 2026/27') then
    raise notice 'Plan już istnieje, nic nie dodano.';
    return;
  end if;

  -- One summary notification instead of one per session.
  perform set_config('vyra.bulk', 'on', true);

